  b jsonb; a jsonb; z jsonb;
  bid uuid; rid uuid; zid uuid;
  keep uuid := (select id from public.buildings where slug = 'autodesk-technology-engagement-center');
begin
  delete from public.rooms where building_id is distinct from keep;
  delete from public.camera_units where mock;
  delete from public.buildings where id is distinct from keep;
  for b in select * from jsonb_array_elements(campus) loop
    insert into public.buildings (name, slug, lat, lng)
      values (b->>'name', b->>'slug', (b->>'lat')::float8, (b->>'lng')::float8) returning id into bid;
    for a in select * from jsonb_array_elements(b->'areas') loop
      insert into public.rooms (building_id, name, slug, description, published)
        values (bid, a->>'name', a->>'slug', a->>'desc', true) returning id into rid;
      for z in select * from jsonb_array_elements(a->'zones') loop
        insert into public.zones (room_id, name, type, capacity, polygon)
          values (rid, z->>'n', z->>'t', (z->>'c')::int, z->'p') returning id into zid;
        insert into public.zone_counts (zone_id, count, updated_at) values (zid, (z->>'count')::int, now());
      end loop;
      insert into public.camera_units (name, room_id, last_seen, mock)
        values ('Mock unit, ' || (b->>'name') || ', ' || (a->>'name'), rid, now(), true);
    end loop;
  end loop;
end $$;
